def path(d,c,stroke='none',width=1):return f'<path d="{d}" fill="{c}" stroke="{stroke}" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round"/>'
def person(x,y,shirt='#39796c',scale=1):
 s=circle(0,-48,14,'#bd835d')+path('M-14 -50 Q-16 -67 0 -66 Q16 -66 14 -47 L8 -53 L-12 -53Z','#382f30')+rect(-19,-31,38,43,10 if False else shirt,10)+path('M-9 9 L-11 34 M10 9 L12 34','none','#304f63',8)+path('M-19 -23 L-29 -3 M19 -23 L28 -4','none','#bd835d',7)
 return f'<g transform="translate({x} {y}) scale({scale})">{s}</g>'
